{
  "name": "@tokenmix/opencode-plugin",
  "version": "0.3.0",
  "description": "OpenCode plugin that adds tokenmix.ai account tools (top-up, model catalog, balance hints) and a chat session usage tracker.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "prepublishOnly": "pnpm build"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "tokenmix",
    "opencode",
    "opencode-plugin",
    "ai",
    "llm",
    "coding-agent"
  ],
  "license": "MIT",
  "homepage": "https://tokenmix.ai",
  "repository": {
    "type": "git",
    "url": "https://github.com/TokenMixAi/tokenmix-opencode-plugin.git"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.10",
    "@opencode-ai/sdk": "^1.15.10",
    "@types/node": "^22.9.0",
    "typescript": "^5.6.3",
    "vitest": "^4.1.7",
    "zod": "^4.1.8"
  },
  "pnpm": {
    "onlyBuiltDependencies": [
      "esbuild"
    ]
  }
}

import { balanceTool } from "./tools/balance.js";
import { topupTool, bindTopupShell } from "./tools/topup.js";
import { modelsTool } from "./tools/models.js";
import { usageTool } from "./tools/usage.js";
import { setTokenmixContext, getTokenmixContext } from "./state.js";
import { resolveBaseUrl, fetchWallet } from "./api/client.js";
import { recordAssistantTokens } from "./usage.js";
import { BalanceMonitor } from "./balance-monitor.js";
import { formatUSD } from "./format.js";
const TOPUP_URL = "tokenmix.ai/dashboard/credits";
const DEFAULT_LOW_BALANCE_USD = 1;
const WALLET_CHECK_INTERVAL_MS = 60_000;
// Heuristic: a string is a tokenmix API key if it starts with sk-tm-.
// We deliberately do NOT cache arbitrary API keys here.
function isTokenmixKey(v) {
    return typeof v === "string" && v.startsWith("sk-tm-");
}
// Plugin entry. OpenCode auto-loads this when `opencode.json` lists
// "@tokenmix/opencode-plugin" in its `plugin` array.
//
// Options (opencode.json: ["@tokenmix/opencode-plugin", { lowBalanceThreshold: 2 }]):
//   lowBalanceThreshold — USD below which a one-time toast warns the user (default 1).
const tokenmixPlugin = async (input, options) => {
    bindTopupShell(input.$);
    const thresholdUsd = typeof options?.lowBalanceThreshold === "number" && options.lowBalanceThreshold >= 0
        ? options.lowBalanceThreshold
        : DEFAULT_LOW_BALANCE_USD;
    const monitor = new BalanceMonitor(thresholdUsd * 1_000_000, WALLET_CHECK_INTERVAL_MS);
    return {
        tool: {
            tokenmix_balance: balanceTool,
            tokenmix_topup: topupTool,
            tokenmix_models: modelsTool,
            tokenmix_usage: usageTool,
        },
        // Sniff the resolved provider config so the wallet tools can call /v1/wallet
        // without forcing the user to configure anything in plugin options.
        // chat.params runs before every LLM call and gives us the fully-resolved provider.
        "chat.params": async (hookInput) => {
            const opts = (hookInput.provider?.options ?? {});
            const apiKey = opts.apiKey ?? opts.api_key;
            const baseURL = (opts.baseURL ?? opts.base_url ?? opts.baseUrl);
            if (isTokenmixKey(apiKey)) {
                setTokenmixContext({
                    apiKey,
                    baseUrl: resolveBaseUrl(typeof baseURL === "string" ? baseURL : null),
                });
            }
        },
        // Track per-session token usage and proactively warn on low balance.
        // Every branch is defensive: a failure here must never disrupt the session.
        event: async ({ event }) => {
            if (event.type === "message.updated") {
                const info = event.properties.info;
                if (info.role === "assistant") {
                    recordAssistantTokens(info.sessionID, info.id, info.tokens?.input ?? 0, info.tokens?.output ?? 0);
                }
                return;
            }
            if (event.type === "session.idle") {
                const ctx = getTokenmixContext();
                if (!ctx)
                    return;
                if (!monitor.shouldCheck(Date.now()))
                    return;
                try {
                    const wallet = await fetchWallet(ctx.baseUrl, ctx.apiKey);
                    const available = wallet.balance + wallet.gift_balance;
                    if (monitor.evaluate(available)) {
                        try {
                            await input.client.tui.showToast({
                                body: {
                                    title: "TokenMix",
                                    message: `Balance low: $${formatUSD(available)} ${wallet.currency} left. Top up at ${TOPUP_URL}`,
                                    variant: "warning",
                                },
                            });
                        }
                        catch {
                            // No TUI attached (headless server) — nothing to show.
                        }
                    }
                }
                catch {
                    // Wallet fetch failed (offline / transient) — retry on the next idle.
                }
            }
        },
    };
};
export default tokenmixPlugin;
//# sourceMappingURL=index.js.map
